Given an array of integers, the task is to insert an element at the end of the array.Examples:Input: arr[] = [10, 20, 30, 40], ele = 50Output: [10, 20, 30, 40, 50]Input: arr[] = [], ele = 20Output: [20]Try It YourselfTable of Content[Approach 1] Using Built-In Methods[Approach 2] Using Custom Method[Approach 1] Using Built-In MethodsWe will use library methods like push_back() in C++, add() in Java and C#, append() in Python and push() in JavaScript.
            C++

    // C++ program to insert given element at the end 
// of an array using built-in methods

#include <iostream>
#include <vector>
using namespace std;

int main() {
    vector<int> arr = {10, 20, 30, 40};
  	int ele = 50;
    cout << "Array before insertion\n";
    for (int i = 0; i < arr.size(); i++)
        cout << arr[i] << " ";

  	// Insert element at the end
    arr.push_back(ele);

    cout << "\nArray after insertion\n";
    for (int i = 0; i < arr.size(); i++)
        cout << arr[i] << " ";

    return 0;
}


            Java

    // Java program to insert a given element at the end of an array
// using built-in methods

import java.util.ArrayList;
import java.util.Arrays;

class GfG {
    public static void main(String[] args) {
        ArrayList<Integer> arr = new 
          			ArrayList<>(Arrays.asList(10, 20, 30, 40));
        int ele = 50;
        System.out.println("Array before insertion");
        for (int i = 0; i < arr.size(); i++)
            System.out.print(arr.get(i) + " ");

        // Insert element at the end
        arr.add(ele);

        System.out.println("\nArray after insertion");
        for (int i = 0; i < arr.size(); i++)
            System.out.print(arr.get(i) + " ");
    }
}


